let offlineState=null,syncConflict=null,syncRunning=false;
function offlineDB(action,key,value){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(Error('Offline storage unavailable'));const request=indexedDB.open('DailyTally-offline',1);request.onupgradeneeded=()=>request.result.createObjectStore('accounts');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const database=request.result,tx=database.transaction('accounts',action==='get'?'readonly':'readwrite'),store=tx.objectStore('accounts');let op;if(action==='get')op=store.get(key);else if(action==='delete')op=store.delete(key);else op=store.put(value,key);tx.oncomplete=()=>{resolve(op.result);database.close()};tx.onerror=()=>{reject(tx.error);database.close()}}})}
async function rememberAccount(){if(!accountPhone)return;offlineState={phone:accountPhone,email:typeof accountEmail==='undefined'?'':accountEmail,emailVerified:typeof accountEmailVerified!=='undefined'&&accountEmailVerified,base:structuredClone(db),data:structuredClone(db),revision:accountRevision,pending:false};try{await offlineDB('put',accountPhone,offlineState);localStorage.setItem('dailytally-active',accountPhone)}catch{}renderSyncStatus()}
async function persistAccountData(){if(!accountPhone)throw Error('আগে লগইন করুন।');if(offlineState?.pending){const queued={...offlineState,data:structuredClone(db)};await offlineDB('put',accountPhone,queued);offlineState=queued;renderSyncStatus();return}try{const result=await accountAPI('data','PUT',{data:db,revision:accountRevision});accountRevision=result.revision;await rememberAccount()}catch(error){if(!error.offline)throw error;if(!offlineState||offlineState.phone!==accountPhone)throw Error('প্রথমে অনলাইনে হিসাব খুলুন।');const pending={...offlineState,data:structuredClone(db),pending:true};await offlineDB('put',accountPhone,pending);offlineState=pending;renderSyncStatus()}}
function mergeOfflineData(base,local,remote){const conflicts=[];const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);function merge(a,b,c,path){if(equal(b,a))return c;if(equal(c,a)||equal(b,c))return b;if([a,b,c].every(v=>Array.isArray(v)&&v.every(i=>i&&typeof i.id==='string'))){const maps=[a,b,c].map(xs=>new Map(xs.map(x=>[x.id,x]))),result=[];for(const key of new Set([...maps[0].keys(),...maps[1].keys(),...maps[2].keys()])){const value=merge(maps[0].get(key),maps[1].get(key),maps[2].get(key),path+'/'+key);if(value!==undefined)result.push(value)}return result}if([a,b,c].every(v=>v&&typeof v==='object'&&!Array.isArray(v))){const result={};for(const key of new Set([...Object.keys(a),...Object.keys(b),...Object.keys(c)])){const value=merge(a[key],b[key],c[key],path+'/'+key);if(value!==undefined)result[key]=value}return result}conflicts.push(path);return b}return {data:merge(base,local,remote,''),conflicts}}
async function syncOfflineChanges(){if(syncRunning||accountBusy||!accountPhone||!offlineState?.pending||document.querySelector('dialog[open]'))return;syncRunning=true;accountBusy=true;try{const remote=await accountAPI('data'),merged=mergeOfflineData(offlineState.base,offlineState.data,remote.data);if(merged.conflicts.length||!valid(merged.data)){syncConflict={local:offlineState.data,remote:remote.data,revision:remote.revision};await offlineDB('put','conflict:'+accountPhone,syncConflict);return}const result=await accountAPI('data','PUT',{data:merged.data,revision:remote.revision});db=merged.data;accountRevision=result.revision;await rememberAccount();render()}catch(error){if(error.status===401){authScreen(false,featureText('আবার লগইন করুন।'))}}finally{accountBusy=false;syncRunning=false;renderSyncStatus();if(typeof retryPendingServerBackup==='function')retryPendingServerBackup()}}
async function hydrateAccount(session,result){accountPhone=session.phone;accountRevision=result.revision;db=result.data;let cached;try{cached=await offlineDB('get',accountPhone)}catch{}if(cached?.pending){offlineState=cached;db=cached.data;accountRevision=cached.revision;await syncOfflineChanges()}else await rememberAccount();try{localStorage.removeItem('dailytally-locked')}catch{}}
async function resumeOfflineAccount(){try{if(localStorage.getItem('dailytally-locked'))return false;const phone=localStorage.getItem('dailytally-active');if(!phone)return false;const cached=await offlineDB('get',phone);if(!cached||!valid(cached.data))return false;offlineState=cached;accountPhone=phone;if(typeof accountEmail!=='undefined'){accountEmail=cached.email||'';accountEmailVerified=!!cached.emailVerified}accountRevision=cached.revision;db=cached.data;tab='ড্যাশবোর্ড';render();document.body.classList.remove('is-auth');if(typeof autoServerBackupOnOpen==='function')void autoServerBackupOnOpen();return true}catch{return false}}
function renderSyncStatus(){let banner=document.querySelector('#sync-status');if(!accountPhone){banner?.remove();return}if(!banner){banner=document.createElement('div');banner.id='sync-status';document.querySelector('main').prepend(banner)}banner.innerHTML=syncConflict?'<span>সিঙ্কে তথ্যের অমিল আছে।</span><button type="button" id="resolve-sync">সমাধান করুন</button>':offlineState?.pending?'<span>ডিভাইসে সংরক্ষিত · সিঙ্ক বাকি</span><button type="button" id="retry-sync">সিঙ্ক করুন</button>':!navigator.onLine?'<span>অফলাইন</span>':'';banner.hidden=!banner.innerHTML;banner.querySelector('#retry-sync')?.addEventListener('click',syncOfflineChanges);banner.querySelector('#resolve-sync')?.addEventListener('click',openSyncConflict)}
function openSyncConflict(){if(!syncConflict)return;const dialog=featureDialog(featureText('সিঙ্কের তথ্য বাছুন'),'<p>দুটি জায়গায় একই তথ্য বদলেছে। আগে ব্যাকআপ ডাউনলোড করুন, তারপর কোন কপি রাখবেন বাছুন।</p><button id="conflict-backup">দুই কপির ব্যাকআপ</button><button id="conflict-local">ডিভাইসের কপি রাখুন</button><button id="conflict-server">সার্ভারের কপি রাখুন</button>');dialog.querySelector('#conflict-backup').onclick=()=>download('DailyTally-sync-backup.json',JSON.stringify(syncConflict,null,2),'application/json');for(const side of ['local','server'])dialog.querySelector('#conflict-'+side).onclick=async()=>{if(accountBusy||!confirm(featureText('নির্বাচিত কপি দিয়ে হিসাব মিলাবেন?')))return;accountBusy=true;try{const current=await accountAPI('data');if(current.revision!==syncConflict.revision){syncConflict.remote=current.data;syncConflict.revision=current.revision;throw Error('সার্ভারে তথ্য বদলেছে। আবার বাছুন।')}const chosen=side==='local'?syncConflict.local:current.data;if(side==='local'){const result=await accountAPI('data','PUT',{data:chosen,revision:current.revision});accountRevision=result.revision}else accountRevision=current.revision;db=chosen;syncConflict=null;await rememberAccount();render()}catch(error){featureError(dialog,error)}finally{accountBusy=false}}}
async function lockLocalAccount(){if(offlineState?.pending&&!confirm(featureText('সিঙ্ক বাকি আছে। লগআউট করলে এই ডিভাইসের অসম্পূর্ণ তথ্য মুছবে। চালিয়ে যাবেন?')))return false;try{localStorage.setItem('dailytally-locked','1');localStorage.removeItem('dailytally-active');if(accountPhone){await offlineDB('delete',accountPhone);await offlineDB('delete','conflict:'+accountPhone)}}catch{}offlineState=null;syncConflict=null;return true}
window.addEventListener('online',()=>{void syncOfflineChanges();renderSyncStatus()});window.addEventListener('offline',renderSyncStatus);
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
